from build import build
S={
'lumbosacral plexus':'The ventral branches of <b>L4–S3</b> that form the nerves of the pelvic limb.',
'obturator nerve':'From <b>L4–L6</b>. It goes through the <b>obturator foramen</b> to the adductors (pectineus, gracilis, adductor). Cut it and the leg slides out sideways.',
'femoral nerve':'From <b>L4–L6</b>, inside the iliopsoas. It supplies the <b>quadriceps</b> (stifle extension) and gives off the <b>saphenous nerve</b>; autonomous zone = medial limb skin.',
'pudendal nerve':'From <b>S1–S3</b>. It runs to the perineum, giving the caudal rectal, perineal and dorsal nerve of the penis/clitoris.',
'caudal rectal nerve':'A pudendal branch to the <b>external anal sphincter</b>.',
'perineal nerves':'Pudendal branches to the <b>perineal skin</b> and muscles.',
'dorsal nerve of the penis':'The <b>end of the pudendal nerve</b>, along the dorsum of the penis (or clitoris in females). Sensory to the glans.',
'caudal cutaneous femoral nerve':'From the sacral plexus to the <b>skin of the caudal thigh</b>.',
'lumbosacral trunk':'The joined <b>L6–S2</b> roots in the pelvis that become the sciatic nerve.',
'cranial gluteal nerve':'From the lumbosacral trunk. It runs with the cranial gluteal artery <b>between the middle and deep gluteals</b> and also supplies the <b>tensor fasciae latae</b>.',
'caudal gluteal nerve':'From the lumbosacral trunk to the <b>superficial gluteal</b> muscle.',
'sciatic nerve':'The biggest nerve, from the <b>lumbosacral trunk</b>. It leaves over the greater ischiatic notch, runs <b>caudal to the hip</b>, and splits into the <b>common fibular + tibial</b> nerves.',
'lateral cutaneous sural nerve':'A branch of the <b>common fibular</b> nerve to the skin of the <b>lateral crus</b>.',
'caudal cutaneous sural nerve':'A branch of the <b>tibial</b> nerve to the skin of the <b>caudal crus</b>.',
'common fibular nerve':'The <b>lateral</b> branch of the sciatic. It crosses the lateral gastrocnemius and splits into superficial + deep fibular nerves. Flexes the tarsus, extends the digits.',
'superficial fibular nerve':'Runs under the fibularis longus to the <b>dorsal paw skin</b>. That dorsal skin is the fibular nerve\'s autonomous zone.',
'deep fibular nerve':'Runs with the <b>cranial tibial artery</b> under the long digital extensor and cranial tibial muscles.',
'perforating branch':'The vessel that <b>perforates between metatarsals II and III</b>, connecting the dorsal and plantar arteries of the paw.',
'tibial nerve':'The <b>medial/caudal</b> branch of the sciatic. It supplies the <b>gastrocnemius + digital flexors</b> (extends the tarsus) and the plantar paw skin (its autonomous zone).',
'tarsal tunnel':'The channel on the <b>plantar-medial tarsus</b> where the tibial nerve branches and flexor tendons pass to the paw.',
}
build(27,'Pelvic limb nerves',S)
